WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى - إصدار وثائق شركات التأمين رقميًا$t1_0$, $b1_0$يجوز لشركات التأمين بعد الحصول على موافقة الهيئة إصدار وثائق التأمين رقميًا من خلال نظم معلومات الشركة ، متى كان إصدار تلك الوثائق والتعرف على العميل من خلال اتباع الأساليب التكنولوجية المقررة بقرارات مجلس إدارة الهيئة أرقام 139 ، 140 ، 141 لسنة 2023 المشار إليها ، على أن تكون تلك الوثائق مبرمة بناءً على العقود الرقمية وبعد التأكد من ربط قاعدة بيانات الشركة مع قاعدة بيانات الهيئة .
ويجوز طباعة الوثائق المشار إليها بواسطة المؤمن له مباشرة وتسويقها وتوزيعها من خلال إحدى الجهات المنصوص عليها بالمادة الخامسة من هذا القرار .$b1_0$
  FROM laws WHERE law_no = 199 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-09-26', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية - إجراءات الحصول على موافقة الهيئة على إصدار وتوزيع وثائق التأمين رقميا$t2_0$, $b2_0$تلتزم شركات التأمين الراغبة في إصدار وإتاحة توزيع وثائقها رقميًا بتقديم طلب للهيئة بذلك مرفقًا به ما يلي :
1- بيان بإجراءات العمل التي ستتبعها الشركة لإصدار وتوزيع وثائق التأمين بما في ذلك استيفاء كافة المتطلبات التأمينية لإصدار تلك الوثائق ، وكذا تعريف العميل بالمنتج التأميني وشروطه بشكل مكتوب ومن خلال فيديو تعريفي ، وما يفيد التحقق رقميًا من اطلاعه على كافة شروط الوثيقة والمخاطر المرتبطة بها وقبوله لهما .
2- تعهد بالالتزام بقرارات مجلس إدارة الهيئة أرقام 139 ، 140 ، 141 لسنة 2023 المشار إليها .
وتتولى الهيئة دراسة الطلب المشار إليه ، ولها طلب استيفاء أي بيانات أو مستندات ترى ضرورة تقديمها للبت في الطلب ، وتبت الهيئة في الطلب المقدم إليها خلال ثلاثين يومًا على الأكثر من تاريخ تقديمه مستوفيًا المستندات المؤيدة له ، على أن يراعى عند دراسة الطلب والبت فيه مدى صدور أحكام قضائية أو تدابير إدارية أو إجراءات رقابية ضد الشركة خلال السنتين السابقتين على تقديم طلب الموافقة .$b2_0$
  FROM laws WHERE law_no = 199 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-09-26', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة - سداد الأقساط المستحقة لشركات التأمين$t3_0$, $b3_0$يجب سداد الأقساط المستحقة على العملاء لشركات التأمين عن الوثائق المصدرة والموزعة رقميًا ، في حسابات شركة التأمين مباشرة من خلال ماكينات نقاط الدفع المسلمة إلى الجهة القائمة بالتسويق والتوزيع ، أو من خلال أي وسيلة دفع غير نقدي خاصة بالشركة ، أو عن طريق وسائل الدفع الإلكتروني المعمول بها والتي من ضمنها الخصم المباشر من الحساب المصرفي أو بطاقات الدفع المصرفية .
ويحظر على أي جهة تتعاقد معها شركة التأمين لتسويق وتوزيع وثائقها تحصيل رسوم أو أقساط التأمين أو غيرها من المبالغ من العملاء بأي وسيلة ينتج عنها إضافة تلك المبالغ إلى حساباتها الخاصة ، وتلتزم بتحصيلها من خلال أي من الطرق المشار إليها بهذه المادة .$b3_0$
  FROM laws WHERE law_no = 199 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-09-26', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة - الضوابط التنفيذية الواجب على شركات التأمين الالتزام بها عند إصدار وثائقها رقميًا$t4_0$, $b4_0$تلتزم شركات التأمين بالضوابط التنفيذية الصادرة عن الهيئة عند إصدار وثائق التأمين وفقًا لأحكام هذا القرار ، على أن تتضمن على وجه الأخص ما يلي :
1- شروط التعاقد بين شركة التأمين والجهة القائمة بالتسويق والتوزيع أو شروط إتاحة طلب الوثيقة مباشرة من قبل العميل .
2- الحد الأدنى من البيانات والإرشادات الواجب عرضها على الشاشة الرقمية لطلب الوثيقة .
3- شروط الوثيقة الواجب الإفصاح عنها وتضمينها فيما يتم طباعته .
4- أن سريان التغطية التأمينية مرتبط بالتحصيل الفعلي لشركة التأمين لأول قسط .
5- جواز اقتصار دور الجهة القائمة بالتسويق والتوزيع على إدخال البيانات الأساسية للعميل من خلال خط الربط الرقمي ، مع عدم السماح لها بإجراء أي تعديلات سواء بالإضافة أو الحذف على شروط الوثيقة إلا من خلال شركة التأمين ذاتها وتحت مسئوليتها ، على أن تلتزم شركة التأمين بالتحقق رقميًا من صحة بيانات الرقم القومي وملكية رقم الهاتف المحمول ومدى إدراجه في قوائم غسل الأموال والمنع من التصرف على النحو المشار إليه بقرار مجلس إدارة الهيئة رقم 186 لسنة 2024 المشار إليه وذلك في كل مرة يقوم فيها العميل بإبرام وثيقة مع الشركة ، مع تعهد العميل بإبلاغ الشركة فور تغيير أي من بياناته التي قام بموافاة الشركة بها .
6- التأكيد على أن يتم إخطار العملاء بأن الجهة القائمة بالتوزيع ما هي إلا قناة للتسويق والتوزيع وغير مسئولة عن شروط وأحكام منتجات التأمين التي يتم تسويقها ولا عن سداد أية تعويضات ، وأن المسئولية تقع على شركة التأمين وحدها .
7- وجود مركز اتصال لدى شركة التأمين لخدمة عملاء التوزيع الرقمي لوثائق التأمين والرد على استفساراتهم وتلقى الشكاوى الخاصة بهم ، على أن تتضمن النسخة المطبوعة من الوثيقة رقم الهاتف والبريد الإلكتروني المحددين للتواصل مع مركز الاتصال المشار إليه .$b4_0$
  FROM laws WHERE law_no = 199 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-09-26', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة - متطلبات قيام شركات التأمين بتسويق وتوزيع وثائقها من خلال إحدى الجهات الأخرى$t5_0$, $b5_0$يشترط لقيام شركات التأمين بتسويق وتوزيع وثائقها من خلال إحدى الجهات الأخرى الالتزام بما يلي :
1- الحصول على موافقة الهيئة على إصدار وتوزيع الوثائق رقميًا على النحو المنصوص عليه بهذا القرار .
2- أن تكون الجهة القائمة بالتسويق والتوزيع من الجهات الآتية :
(أ) وسطاء التأمين الرقميين المقيدين لدى الهيئة .
(ب) البنوك المسجلة لدى البنك المركزي المصري .
(ج) بنك ناصر الاجتماعي .
(د) الهيئة القومية للبريد .
(ه) شركات الطيران .
(و) شركات الاتصالات أو المتاجر الإلكترونية .
(ز) قنوات التوزيع الأخرى المنصوص عليها بالضوابط التنفيذية لإصدار وتوزيع وثائق التأمين متناهي الصغر إلكترونيًا .
وفي جميع الأحوال ، يشترط حصول الفئات المشار إليها على التراخيص اللازمة لمزاولة نشاطها من الجهات المختصة حال تطلب ذلك وكذا الحصول على موافقة تلك الجهات على قيام الفئات المذكورة بهذا البند بتسويق وتوزيع وثائق التأمين وفقًا لهذا القرار .
3- تقديم نسخة للهيئة من العقد المزمع إبرامه مع الجهة القائمة بالتسويق والتوزيع على أن تتضمن بحد أدنى البيانات الآتية :
(أ) أنواع وثائق التأمين التي سيتم تسويقها وتوزيعها من خلال الجهة المتعاقد معها.
(ب) تعهد الطرفين بالحفاظ على سرية البيانات وخصوصية المعلومات التي تخص كل منهما وكذا التي تخص العملاء .
(ج) خطة الجهة المتعاقد معها في تسويق وتوزيع وثائق شركة التأمين .
(د) تحديد المنافذ التي سيتم التسويق والتوزيع من خلالها .
(ه) الالتزامات التعاقدية الأخرى بما في ذلك الأعباء المالية لكل طرف من أطراف التعاقد .
وتقوم شركات التأمين بتقديم طلب للهيئة لتسويق وتوزيع وثائقها من خلال إحدى الجهات المشار إليها بهذه المادة ، وتتولى الهيئة دراسة الطلب المشار إليه ، ولها طلب استيفاء أي بيانات أو مستندات ترى ضرورة تقديمها للبت في الطلب ، وتبت الهيئة في الطلب المقدم إليها خلال ثلاثين يومًا على الأكثر من تاريخ تقديمه مستوفيًا للمستندات المؤيدة له .$b5_0$
  FROM laws WHERE law_no = 199 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-09-26', 'active' FROM ins5_0;

