DO $verify161$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 199 AND law_year = 2025 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[161] القرار 199/2025 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 9 THEN RAISE EXCEPTION '[161] عدد المواد % بدل 9', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2025-09-26';
  IF v_v <> 9 THEN RAISE EXCEPTION '[161] عدد النسخ % بدل 9', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%ة ال يع%' OR body LIKE '%ه ال يع%' OR body LIKE '%تد بها%' OR body LIKE '% تروني%' OR body LIKE '%ل تداول%' OR body LIKE '%لك تروني%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%المصرية العدد 214%' OR body LIKE '%صورة إ%' OR body LIKE '%وفق ا%' OR body LIKE '%رقمي ا%' OR body LIKE '%مرفق ا%' OR body LIKE '%مستوفي ا%' OR body LIKE '%الكتروني ا%' OR body LIKE '%ي شترط%' OR body LIKE '%ي راعي%' OR body LIKE '%وي حظر%' OR body LIKE '%ي لغى%' OR body LIKE '%ي نشر%' OR body LIKE '%وي عمل%' OR body LIKE '%141 ، 140%' OR body LIKE '%902 ، 730%' OR body LIKE '%2023المشار%' OR body LIKE '%2016المشار%' OR body LIKE '%2015المشار%' OR body LIKE '%186لسنة%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[161] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظ%' AND body LIKE '%تاريخي 2025/8/13 و 2025/9/10 ؛' AND body LIKE '%رقم 10 لسنة 2009%' AND body LIKE '%رقم 5 لسنة 2022%' AND body LIKE '%رقم 155 لسنة 2024%' AND body LIKE '%رقم 122 لسنة 2015%' AND body LIKE '%رقم 69 لسنة 2023%' AND body LIKE '%رقم 139 لسنة 2023%' AND body LIKE '%رقم 140 لسنة 2023%' AND body LIKE '%رقم 141 لسنة 2023%' AND body LIKE '%رقم 186 لسنة 2024 بشأن الالتزام بالاستعلام عن صحة بيانات العملاء ؛ وعلى قرار مجلس إدارة الهيئة رقم 198 لسنة 2025%' AND body LIKE '%رقم 729 لسنة 2016%' AND body LIKE '%رقم 730 لسنة 2016%' AND body LIKE '%رقم 902 لسنة 2016%' AND body LIKE '%بتاريخي 2025/8/13 و 2025/9/10 ؛%') THEN RAISE EXCEPTION '[161] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'يجوز لشركات التأمين بعد الحصول على موافقة اله%' AND body LIKE '%المادة الخامسة من هذا القرار .' AND body LIKE '%أرقام 139 ، 140 ، 141 لسنة 2023 المشار إليها%' AND body LIKE '%المادة الخامسة من هذا القرار .%') THEN RAISE EXCEPTION '[161] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'تلتزم شركات التأمين الراغبة في إصدار وإتاحة ت%' AND body LIKE '%بقتين على تقديم طلب الموافقة .' AND body LIKE '%1- بيان بإجراءات العمل%' AND body LIKE '%2- تعهد بالالتزام بقرارات مجلس إدارة الهيئة أرقام 139 ، 140 ، 141 لسنة 2023 المشار إليها .%' AND body LIKE '%خلال ثلاثين يومًا على الأكثر%') THEN RAISE EXCEPTION '[161] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'يجب سداد الأقساط المستحقة على العملاء لشركات%' AND body LIKE '%طرق المشار إليها بهذه المادة .' AND body LIKE '%وتلتزم بتحصيلها من خلال أي من الطرق المشار إليها بهذه المادة .%') THEN RAISE EXCEPTION '[161] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'تلتزم شركات التأمين بالضوابط التنفيذية الصادر%' AND body LIKE '%مع مركز الاتصال المشار إليه .' AND body LIKE '%رقم 186 لسنة 2024 المشار إليه وذلك%' AND body LIKE '%7- وجود مركز اتصال%') THEN RAISE EXCEPTION '[161] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'يشترط لقيام شركات التأمين بتسويق وتوزيع وثائق%' AND body LIKE '%ستوفيًا للمستندات المؤيدة له .' AND body LIKE '%(أ) وسطاء التأمين الرقميين المقيدين لدى الهيئة .%' AND body LIKE '%(ه) شركات الطيران .%' AND body LIKE '%(ز) قنوات التوزيع الأخرى%' AND body LIKE '%(أ) أنواع وثائق التأمين التي سيتم تسويقها وتوزيعها من خلال الجهة المتعاقد معها.%' AND body LIKE '%(ه) الالتزامات التعاقدية الأخرى%' AND body LIKE '%3- تقديم نسخة للهيئة%') THEN RAISE EXCEPTION '[161] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'يستمر العمل بقرارات رئيس الهيئة أرقام 729 ، 7%' AND body LIKE '%، 141 لسنة 2023 المشار إليها .' AND body LIKE '%أرقام 729 ، 730 ، 902 لسنة 2016 المشار إليها%' AND body LIKE '%أرقام 139 ، 140 ، 141 لسنة 2023 المشار إليها .%') THEN RAISE EXCEPTION '[161] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'يلغى قرار مجلس إدارة الهيئة رقم 122 لسنة 2015%' AND body LIKE '%ل حكم يخالف أحكام هذا القرار .' AND body LIKE '%رقم 122 لسنة 2015 المشار إليه%') THEN RAISE EXCEPTION '[161] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية وعلى الموق%' AND body LIKE '%د. محمد فريد صالح' AND body LIKE '%ويعمل به من اليوم التالي لتاريخ نشره بالوقائع المصرية .%' AND body LIKE '%د. محمد فريد صالح') THEN RAISE EXCEPTION '[161] المادة 8 غير سليم'; END IF;
  IF v_len <> 7598 THEN RAISE EXCEPTION '[161] إجمالى طول المواد % بدل 7598', v_len; END IF;
  RAISE NOTICE '[161] القرار 199/2025: 9 مواد و9 نسخ، إجمالى % حرف', v_len;
END
$verify161$;

COMMIT;
